import itertools
from typing import Dict, List
from problems import ThreeSat, DominatingSet


def solve_three_sat(instance: Dict) -> bool:
    ThreeSat.validate(instance)
    m = instance["num_vars"]
    clauses: List[List[int]] = instance["clauses"]
    # iterate over all assignments of m variables
    for bits in itertools.product([False, True], repeat=m):
        ok = True
        for clause in clauses:
            satisfied = False
            for lit in clause:
                var = abs(lit) - 1
                val = bits[var]
                if lit > 0 and val:
                    satisfied = True
                if lit < 0 and not val:
                    satisfied = True
                if satisfied:
                    break
            if not satisfied:
                ok = False
                break
        if ok:
            return True
    return False


def solve_dominating_set(instance: Dict) -> bool:
    DominatingSet.validate(instance)
    n = instance["n"]
    edges = instance["edges"]
    k = instance["k"]
    if k < 0:
        return False
    # build adjacency list including self
    adj = [set([i]) for i in range(n)]
    for u, v in edges:
        adj[u].add(v)
        adj[v].add(u)
    # try all subsets up to size k
    for r in range(k + 1):
        for combo in itertools.combinations(range(n), r):
            dominated = set()
            for v in combo:
                dominated.update(adj[v])
            if len(dominated) == n:
                return True
    return False

if __name__ == "__main__":
    import json, sys
    data = json.load(sys.stdin)
    if data.get("type") == "3sat":
        print(solve_three_sat(data["instance"]))
    else:
        print(solve_dominating_set(data["instance"]))
EOF"}

